/// Generated by Claude Opus 5.5 at medium effort
use image::RgbaImage;
use ratatui::{Frame, layout::Rect, style::Color};

pub fn draw_png(frame: &mut Frame, path: &str) -> image::ImageResult<()> {
    let img = image::open(path)?.to_rgba8();
    let area = frame.area();
    draw_image(frame, &img, area);
    Ok(())
}

pub fn draw_image(frame: &mut Frame, img: &RgbaImage, area: Rect) {
    let buf = frame.buffer_mut();

    // pixel lookup: None if off the image or transparent
    let px = |x: u32, y: u32| -> Option<Color> {
        if x >= img.width() || y >= img.height() {
            return None;
        }
        let [r, g, b, a] = img.get_pixel(x, y).0;
        (a >= 128).then_some(Color::Rgb(r, g, b))
    };

    for row in 0..area.height {
        for col in 0..area.width {
            let (x, y) = (col as u32, row as u32 * 2);
            let (top, bot) = (px(x, y), px(x, y + 1));
            let Some(cell) = buf.cell_mut((area.x + col, area.y + row)) else {
                continue;
            };

            match (top, bot) {
                (Some(t), Some(b)) => {
                    cell.set_char('▀').set_fg(t).set_bg(b);
                }
                (Some(t), None) => {
                    cell.set_char('▀').set_fg(t);
                }
                (None, Some(b)) => {
                    cell.set_char('▄').set_fg(b);
                }
                (None, None) => {}
            }
        }
    }
}
